window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0569a8d0a1b9d01b"]={"versions": [{"id": "FIG-0569a8d0a1b9d01b", "releases": ["R2.1.20", "R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm im Kontext der AUTOSAR Classic Platform (Communication Stack / FlexRay Network Management). Dargestellt ist die vertikale Schichtung und Einbettung des FlexRay-spezifischen Netzwerkmanagement-Moduls in den AUTOSAR NM-Stack innerhalb eines Diagrammrahmens mit dem Titelkopf <code>id AUTOSAR NM Stac...</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei vertikal übereinander angeordnete BSW-Software-Komponenten (UML-Komponenteninstanzen mit Stereotyp-Icon):</p>\n<ul class=\"fig-list\"><li><code>:Nm</code>: Generische Netzwerkmanagement-Schnittstelle (Network Management Interface) auf oberster Ebene.\n</li><li><code>:FrNm</code>: FlexRay Network Management Modul als busspezifische NM-Instanz in der mittleren Ebene.\n</li><li><code>:FrIf</code>: FlexRay Interface als Abstraktionsschicht darunter.\n</li></ul>\n<p class=\"fig-p\">Es sind keine expliziten Konnektoren, Ports oder Schnittstellenbeziehungen zwischen den Komponenten eingezeichnet.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Komponentenschaubild ohne Darstellung von dynamischen Sequenzen, Kontrollflüssen, Funktionsaufrufen oder Nachrichtenaustausch. Die Anordnung verdeutlicht ausschließlich die logische Schichtung des Stacks (<code>:Nm</code> über <code>:FrNm</code> über <code>:FrIf</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für die Zuordnung und Schichtung des Moduls <code>FrNm</code> im AUTOSAR BSW-Kommunikationsstack: <code>FrNm</code> operiert unterhalb des generischen <code>Nm</code> und greift auf Dienste der FlexRay-Schnittstelle <code>FrIf</code> zu. Entwickler müssen die protokoll- und architecturespezifischen Schnittstellen gemäß den jeweiligen BSW-Spezifikationen (<code>Nm</code>, <code>FrNm</code>, <code>FrIf</code>) implementieren bzw. konfigurieren.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c3e9ad72fbd86343", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm im Kontext der AUTOSAR Classic Platform (Communication Stack / FlexRay Network Management). Dargestellt ist die vertikale Schichtung und Einbettung des FlexRay-spezifischen Netzwerkmanagement-Moduls in den AUTOSAR NM-Stack innerhalb eines Diagrammrahmens mit dem Titelkopf <code>id AUTOSAR NM Stac...</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei vertikal übereinander angeordnete BSW-Software-Komponenten (UML-Komponenteninstanzen mit Stereotyp-Icon):</p>\n<ul class=\"fig-list\"><li><code>:Nm</code>: Generische Netzwerkmanagement-Schnittstelle (Network Management Interface) auf oberster Ebene.\n</li><li><code>:FrNm</code>: FlexRay Network Management Modul als busspezifische NM-Instanz in der mittleren Ebene.\n</li><li><code>:FrIf</code>: FlexRay Interface als Abstraktionsschicht darunter.\n</li></ul>\n<p class=\"fig-p\">Es sind keine expliziten Konnektoren, Ports oder Schnittstellenbeziehungen zwischen den Komponenten eingezeichnet.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Komponentenschaubild ohne Darstellung von dynamischen Sequenzen, Kontrollflüssen, Funktionsaufrufen oder Nachrichtenaustausch. Die Anordnung verdeutlicht ausschließlich die logische Schichtung des Stacks (<code>:Nm</code> über <code>:FrNm</code> über <code>:FrIf</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für die Zuordnung und Schichtung des Moduls <code>FrNm</code> im AUTOSAR BSW-Kommunikationsstack: <code>FrNm</code> operiert unterhalb des generischen <code>Nm</code> und greift auf Dienste der FlexRay-Schnittstelle <code>FrIf</code> zu. Entwickler müssen die protokoll- und architecturespezifischen Schnittstellen gemäß den jeweiligen BSW-Spezifikationen (<code>Nm</code>, <code>FrNm</code>, <code>FrIf</code>) implementieren bzw. konfigurieren.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-0569a8d0a1b9d01b", "to": "FIG-c3e9ad72fbd86343", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
